SELECT id, book_id AS bookId, page_no AS pageNo, type, ori_text AS oriText, annotation,
       md_content AS mdContent, pdf_ocr_ori_content AS pdfOcrOriContent, create_time AS createTime, update_time AS updateTime
FROM page
WHERE book_id = #{bookId}
  AND page_no = #{pageNo}
LIMIT 1
